-- ─────────────────────────────────────────────────────────────
-- SEND 3 v2 · ADHD, autism and dyslexia (staff CPD, staff-led)
-- Monika's v2 (32 steps), with these changes:
--   steps 4, 9 and 15: a watch-for question on the touch screens, read out before Play;
--   step 12: the table wheel lists 4 tables;
--   step 22: Spot the difference is done at the tables from the big screen
--            (list the changes, tag each H / N / L, name what did not change),
--            so there is no move to the screens and no tapping;
--   steps 17 and 24: slides 8 and 14 (the carousel and plan instructions)
--            on the touch screens, because the timers hide the big screen.
-- Pictures: lesson-media/lessons/send3v2/ (22 slides and 2 task sheets).
-- Replaces any earlier SEND 3 lesson with the same title.
-- ─────────────────────────────────────────────────────────────

delete from slots
where session_id is null
  and lesson_id in (select id from lessons where title = 'SEND 3: ADHD, Autism and Dyslexia');
delete from lessons
where title = 'SEND 3: ADHD, Autism and Dyslexia';
with new_lesson as (
  insert into lessons (title, description, estimated_duration_mins, featured, ai_generated, generated_at, ai_notes)
  values (
    'SEND 3: ADHD, Autism and Dyslexia',
    'Staff CPD with Disability Services. Three learners, Kai, Amira and Ryan, each followed by four boxes at the tables, one activity and a strategy card. Staff then spin the swap, spot the difference, sort the college toolkit and plan for one learner in Lesson Weaver with a Digital Companion, and finish with myth or truth, what to say, questions and a pledge.',
    60,
    false,
    true,
    now(),
    '{"rationale": "Monika Worthington''s SEND 3 staff session, rebuilt to be staff-led: fewer slides, more for staff to do. One idea: you can plan for a learner''s need before anyone tells you about it, using three strategies and the college''s own systems. Each learner round: full-focus video, four boxes at the tables before anything is explained (questions on the touch screens, not from the front), one activity (word cloud, vote and wheel, or carousel), then a silent reveal and one strategy card. Apply turns it into practice: spin the swap, spot the difference, sort the toolkit, then a real plan in Lesson Weaver and a Digital Companion, self-checked against six criteria and posted. Disability Services speak through the buzzer quiz, the what-would-you-say vote and the table questions rather than short talks. Changes from the previous build: 32 steps instead of 44; the Understand and Tools slides replaced by activities; the word cloud is agreed per table; the test-each-other step cut for time, with the self-check moved into the plan and the post.", "objectives": ["Identify the barrier each of Kai, Amira and Ryan meets, in the table''s four boxes.", "Explain which strategy removes each barrier and which college tool supports it.", "Analyse what each barrier costs the learner now and by the end of the course.", "Plan a lesson for one learner in Lesson Weaver, adapt one task in its Digital Companion, check it against six criteria, and post it by 0:48:30."], "run_sheet": [{"slot_index": 0, "teacher_says": "Welcome. Scan the QR and set up your Companion, tap how confident you feel on a touch screen, then talk about the question on your table.", "watch_for": "Learners: arriving past the touch screens, then at the tables. Four boxes and the arrival question already on every table: \"Think of a learner you found hard to reach. What did you try?\" No names. Technique: baseline confidence, compared on the way out."}, {"slot_index": 1, "teacher_says": "We start with a short video of a learner, then your tables do the work.", "watch_for": "Learners: at the tables. Thirty seconds. Technique: share the plan first (no surprises)."}, {"slot_index": 2, "teacher_says": "How do you plan for a learner whose needs nobody has told you about? We answer it at the end.", "watch_for": "Learners: at the tables. No answers yet. The four objectives climb; each is checked by something staff do. Technique: a hook the last step answers."}, {"slot_index": 3, "teacher_says": "Watch for: the exact moment the lesson stops working for Kai. Nobody talks until it ends.", "watch_for": "Learners: at the tables, full focus. Press Play; move on when it ends. Technique: full-focus video."}, {"slot_index": 4, "teacher_says": "Everyone write your own word for how Kai felt. Then agree one as a table, and a runner adds it on a touch screen.", "watch_for": "Learners: at the tables, then one runner per table. Ask: did anyone write \"lazy\"? Stretch: which word would his teacher have chosen? Technique: think alone, agree together, send a runner."}, {"slot_index": 5, "teacher_says": "Fill in the four boxes for Kai as a table. The questions are on the touch screens.", "watch_for": "Learners: at the tables. Add Timer 3:30 from your phone. Circulate and push: \"What in his words tells you that?\" \"What are we assuming?\" Technique: attempt before the reveal."}, {"slot_index": 6, "teacher_says": "(Read the reveal aloud: the clip is silent.)", "watch_for": "Learners: at the tables. Technique: reveal after prediction."}, {"slot_index": 7, "teacher_says": "Hide the pile. Compare it with your Needs now box: what did you get that the card hasn''t? Say it back.", "watch_for": "Learners: at the tables. Kai''s support agreement was already on EBS. Disability Services, one line if wanted: hyperfocus is common in ADHD. Photograph the boxes, then wipe."}, {"slot_index": 8, "teacher_says": "Watch for: the teacher''s words that could mean three different things. Nobody talks until it ends.", "watch_for": "Learners: at the tables, full focus."}, {"slot_index": 9, "teacher_says": "Fill in the four boxes for Amira.", "watch_for": "Learners: at the tables. Add Timer 3:00. Technique: attempt before the reveal."}, {"slot_index": 10, "teacher_says": "Agree one answer as a table. One runner votes on a touch screen.", "watch_for": "Learners: at the tables, one runner per table. A and C both look right: that is the point. Technique: best-answer vote."}, {"slot_index": 11, "teacher_says": "The wheel picks a table: defend your vote. \"Don''t overthink it.\" What did the teacher mean, and what did Amira hear?", "watch_for": "Learners: at the tables. Any table can answer back. Technique: justify a position."}, {"slot_index": 12, "teacher_says": "(Read the reveal aloud: the clip is silent.)", "watch_for": "Learners: at the tables."}, {"slot_index": 13, "teacher_says": "No surprises. Compare with your boxes and say it back. This session sent its outline with the invite: who noticed?", "watch_for": "Learners: at the tables. Amira chose not to disclose: nothing on EBS would have warned you. Photograph, wipe."}, {"slot_index": 14, "teacher_says": "Watch for: what Ryan knows but can''t show. Nobody talks until it ends.", "watch_for": "Learners: at the tables, full focus. Write the carousel instruction on the whiteboard now: the rotation timer hides the slide."}, {"slot_index": 15, "teacher_says": "Fill in the four boxes for Ryan. Then wait for the carousel.", "watch_for": "Learners: at the tables. Add Timer 3:00."}, {"slot_index": 16, "teacher_says": "Move one table clockwise, all together. Read their boxes and add one idea to Needs now.", "watch_for": "Learners: WHOLE-CLASS MOVE 1, one table on and back. Technique: build on another table''s work."}, {"slot_index": 17, "teacher_says": "(Read the reveal aloud: the clip is silent.)", "watch_for": "Learners: back at their own tables."}, {"slot_index": 18, "teacher_says": "Lower the language, not the thinking. Compare and say it back.", "watch_for": "Learners: at the tables. Ryan has never been assessed: only an assessment can say, so never tell a learner they are dyslexic. Disability Services, one line: exam access arrangements, refer early. Photograph, wipe."}, {"slot_index": 19, "teacher_says": "None of them needs a diagnosis. For every learner: ask them what helps.", "watch_for": "Learners: at the tables. The turning point from the learners to your lessons."}, {"slot_index": 20, "teacher_says": "The wheel lands on something teachers say. Thirty seconds: rewrite it on your table, then hold it up. The room picks the best.", "watch_for": "Learners: at the tables, whiteboard pens. Four or five spins. Ask the winning table which strategy it used. Technique: retrieval through rewriting, fast and competitive."}, {"slot_index": 21, "teacher_says": "Same task sheet, before and after, on the big screen. As a table: list every change, and tag each one H (hide the pile), N (no surprises) or L (lower the language). Then: what is the one thing that did not change?", "watch_for": "Learners: at the tables, no move. The touch screens show each sheet close up for a runner who wants a better look. Answers, with the strategy each uses: the plan, the time and what finished looks like at the top (N); Step 1 of 4, one step at a time (H); tick boxes (H); key words taught first (L); the matrix on the sheet, not copied from the board (L); Listen to this sheet (L); write it or record it (L); a clear layout (L). Some fit two: accept a good argument. Unchanged: the thinking (still rate, control, justify, summarise). Ask one table for its tags, then another to challenge one. Technique: analyse a worked example before building your own."}, {"slot_index": 22, "teacher_says": "In pairs on your tablet: sort the college tools into understand the need, adapt the lesson, and learners'' own tools.", "watch_for": "Learners: at the tables, in pairs on tablets (link: canva.com/design/DAHb0XovLpo/kRah0QLTu9A3nxVpZ3wCiw/view). Hand out the cheat sheets at the end. Technique: retrieve before you''re told."}, {"slot_index": 23, "teacher_says": "Each table builds for the learner the wheel lands on.", "watch_for": "Learners: at the tables. Spin once per table. Write the plan slide''s steps on the whiteboard now: the countdown hides it."}, {"slot_index": 24, "teacher_says": "In pairs, one tablet: notes box (the need, not the label, and one strategy), generate the plan, make the Companion, pick one task and up to three scaffolds, then check it in the learner view against the six checks.", "watch_for": "Learners: at the tables in pairs. Touch Screen 2 shows the six checks; check 6 matters most. Stretch: plan when each scaffold comes away. Circulate: \"Which task, and why? What will he notice first?\" Technique: create, then self-check against criteria."}, {"slot_index": 25, "teacher_says": "One of you types your notes on a touch screen. The other keeps testing.", "watch_for": "Learners: one runner per pair. As the board fills, read two posts aloud: \"What will that learner notice first?\" This board is the evidence of learning. Technique: capture the product."}, {"slot_index": 26, "teacher_says": "Everyone to the touch screens, one team at each. Buzz, then say myth or truth. A different person buzzes each time.", "watch_for": "Learners: WHOLE-CLASS MOVE 2. Disability Services add one line after each answer: this is where the condition knowledge lands. Technique: fast recall, competitive."}, {"slot_index": 27, "teacher_says": "Back to your tables. Thirty seconds: write the opening line you would use with Ryan. Then a runner votes: which of these would you say?", "watch_for": "Learners: at the tables, one runner per table. Disability Services: why B. In private; start with what they do well; say what you noticed, not a label; never name a condition, offer support and ask what helps. Then ask a table to read its own line. Technique: rehearse the words."}, {"slot_index": 28, "teacher_says": "Disability Services: your questions from the table corners, and who to go to.", "watch_for": "Learners: at the tables. Touch Screen 2 shows next steps (STEP and Big 4) to photograph. CHECK slide 19 has the real referral route and timescales before the session."}, {"slot_index": 29, "teacher_says": "Start one thing, stop one thing, and think of one learner, no names. On your table and your cheat sheet.", "watch_for": "Learners: at the tables, on their own. Photograph each table."}, {"slot_index": 30, "teacher_says": "How do you plan for a learner whose needs nobody has told you about? Say them back. Check EBS. Use the tools. Ask the learner. Before you go: log in to ThreadWorks to accept your tag.", "watch_for": "Learners: at the tables. One spare minute is built in before the exit. One week: a short quiz. Two weeks: rebuild one of your own lessons. Technique: close the loop the hook opened."}, {"slot_index": 31, "teacher_says": "Same question as when you arrived. Tap it on your way out.", "watch_for": "Learners: leaving past the touch screens. The big screen compares Start and Final."}], "verify_before_teaching": ["The 22 slides and the two task sheets are in the media storage at lesson-media/lessons/send3v2/.", "The six videos are Edpuzzle embeds on the big screen (steps 4, 7, 9, 13, 15, 18). Press Play on each and move on when it ends. Check the sound, and play each one through once before the session.", "Slide 1 still shows [Companion QR] and [time]; slide 19 still shows [Route and timescales] and [Route]. Fix, re-export and re-upload with the same file names.", "Wheel in step 12 lists Table 1 to 4. If the number of tables changes, edit it in the designer.", "Open the Sort the toolkit Canva Code on each tablet before the session and play it through once on a touch screen.", "Tablets logged in to Lesson Weaver, one per pair. Step 25 is 11 minutes.", "Write the carousel instruction and the plan slide''s steps on the whiteboard before the timers hide them (steps 17 and 25). Start Add Timer from the remote in steps 6, 10 and 16.", "Disability Services: confirm the referral route and timescales, the Student Services route and the email on the cheat sheet.", "Cheat sheets printed two-sided, one per person, handed out at step 23.", "Click through the preview: 32 steps, all three screens."], "safety_note": "Never tell a learner they have a condition; only an assessment can say. Follow Disability Services'' current referral route."}'
  )
  returning id
)
